#!/bin/bash

# Evaluation sweep over the TRAINED connector checkpoints (the `txf` configs generated by
# tools/preprocess/create_yamls_models_lalm_txf.py), on both evaluation domains.
#
# HOW THIS DIFFERS FROM eval_lalm_decoder.sh. That script sweeps the *untrained* model configs
# (stock encoder + stock decoder + randomly-initialised connector) across every dataset, which
# is a full model x dataset cross product. This one evaluates each trained checkpoint on the
# language it was TRAINED on, because the checkpoints are language-specific: a connector
# trained on Urdu has no claim on Hausa, and running the full 82 x 22 cross product would be
# ~1800 evaluations, almost all of them meaningless.
#
# So the sweep is a matched pairing, and it is written explicitly rather than looped, because
# the language a checkpoint was trained on is baked into its config name and the eval sets it
# should be paired with are not derivable from that name alone:
#
#   training config    ->  held-out domain (FLEURS)     +  in-domain (WorldSpeech)
#   en_us              ->  fleurs_en_us_test            +  worldspeech_en_us_test
#   fr_ca              ->  fleurs_fr_fr_test            +  worldspeech_fr_ca_test
#   es_mx              ->  fleurs_es_419_test           +  worldspeech_es_mx_test
#   ...
#
# Note fr_ca -> fleurs_fr_fr and es_mx -> fleurs_es_419: the training variety and the FLEURS
# evaluation variety are not the same string, which is exactly the accent axis the analysis
# tracks. Getting this pairing wrong would silently evaluate the wrong cell.
#
# BOTH CHECKPOINTS PER CELL. Every cell has a best-step and a step-1000 checkpoint, and both
# are swept: the study reports best-checkpoint CER as primary and final as secondary, and the
# gap between them is itself the overfitting metric. Evaluating only one answers a different
# question.
#
# Serial 421 pairs with eval_lalm_decoder.sh's 420, matching this repo's convention of giving
# a sweep and its variant adjacent serials.
#
# NOT COVERED: am_et and crs_sc have finished W&B runs but no uploaded checkpoints yet, and
# es_es was superseded by es_mx (its checkpoints have no step-1000). Add them here once
# create_yamls_models_lalm_txf.py reports them.

# (model config stem, FLEURS eval config, WorldSpeech eval config)
# The model stem omits the `_{step}` suffix; the loop below appends both steps.
PAIRINGS=(
    "en_us|short_ml/fleurs_en_us_test.yaml|short_ml/worldspeech_en_us_test.yaml"
    "fr_ca|short_ml/fleurs_fr_fr_test.yaml|short_ml/worldspeech_fr_ca_test.yaml"
    "es_mx|short_ml/fleurs_es_419_test.yaml|short_ml/worldspeech_es_mx_test.yaml"
    "hi_in|short_ml/fleurs_hi_in_test.yaml|short_ml/worldspeech_hi_in_test.yaml"
    "id_id|short_ml/fleurs_id_id_test.yaml|short_ml/worldspeech_id_id_test.yaml"
    "mr_in|short_ml/fleurs_mr_in_test.yaml|short_ml/worldspeech_mr_in_test.yaml"
    "sw_ke|short_ml/fleurs_sw_ke_test.yaml|short_ml/worldspeech_sw_ke_test.yaml"
    "ta_in|short_ml/fleurs_ta_in_test.yaml|short_ml/worldspeech_ta_in_test.yaml"
    "ur_pk|short_ml/fleurs_ur_pk_test.yaml|short_ml/worldspeech_ur_pk_test.yaml"
    "ha_ng|short_ml/fleurs_ha_ng_test.yaml|"
)

# ha_ng has no WorldSpeech entry: the training runs ALREADY evaluate it on
# disco-eth/WorldSpeech test, so an in-domain config here would duplicate an existing cell.

VARIANTS=(
    "earth"
    "fire"
    "global"
    "water"
    # base exists for ta_in only -- handled by the existence check in the loop.
    "base"
)

models=''

VALID_ARGS=$(getopt -o '' --long models: -- "$@")
if [[ $? -ne 0 ]]; then
    exit 1;
fi

eval set -- "$VALID_ARGS"
while [ : ]; do
  case "$1" in
    --models)
        models=${2}
        shift 2
        ;;
    --) shift;
        break
        ;;
  esac
done

if [ -n "$models" ]; then
    read -ra VARIANTS <<< "$models"
fi

base_cmd="python -m tools.evaluate --serial 421 --batch_size 128"

for pairing in "${PAIRINGS[@]}"; do
    IFS='|' read -r lang fleurs_cfg ws_cfg <<< "$pairing"

    for variant in "${VARIANTS[@]}"; do
        # Both checkpoints per cell: the best step (whatever it was) and step 1000. The best
        # step differs per cell, so the config is found by glob rather than assumed.
        for model_cfg_path in configs/models/cq2a_whisper_medium_tiny_aya_${variant}_txf_ws_${lang}_*.yaml; do
            [ -e "$model_cfg_path" ] || continue
            model_cfg=$(basename "$model_cfg_path")

            for dataset_cfg in "$fleurs_cfg" "$ws_cfg"; do
                [ -n "$dataset_cfg" ] || continue
                cmd="$base_cmd --config configs/models/$model_cfg configs/datasets/$dataset_cfg"
                echo "$cmd"
                $cmd
            done
        done
    done
done
